INSERT INTO `academia_cursos` VALUES (2541,'matematicas','Enseñanza Efectiva de las Matemáticas','Objetivo general del curso: Capacitar a los educadores en las teorías, metodologías, estrategias, TICs y técnicas de evaluación para la enseñanza de las matemáticas, con el fin de…','Objetivo general del curso: Capacitar a los educadores en las teorías, metodologías, estrategias, TICs y técnicas de evaluación para la enseñanza de las matemáticas, con el fin de desarrollar habilidades pedagógicas que fomenten el pensamiento lógico-matemático, la creatividad y el interés por las matemáticas, creando un ambiente de aprendizaje significativo y autónomo para los estudiantes.','https://academiacabsa.com/wp-content/uploads/2025/07/young-male-teacher-wearing-glasses-explaining-lesson-happy-positive-smiling-standing-near-blackboard-with-mathematical-formulas-classroomfx-1-600x400-1.jpg','Matemáticas',41,'published','2013-01-11 15:31:24','2013-01-11 15:31:24','2026-07-29 19:46:19',0),(2548,'dinero-y-ahorro','Dinero y Ahorro para Niños y Jóvenes.','Objetivo general del curso: Capacitar a los niños y jóvenes sobre conceptos básicos de dinero, ahorro e inversión, este curso utiliza juegos y actividades interactivas para hacer…','Objetivo general del curso: Capacitar a los niños y jóvenes sobre conceptos básicos de dinero, ahorro e inversión, este curso utiliza juegos y actividades interactivas para hacer que el aprendizaje sea divertido y significativo. Los niños aprenderán sobre el valor del dinero y cómo tomar decisiones financieras informadas.','https://academiacabsa.com/wp-content/uploads/2025/07/00002-2359967846-600x400-1.png','Desarrollo integral',7,'published','2013-01-11 16:39:20','2013-01-11 16:39:20','2026-08-05 17:04:23',0),(2556,'pensamiento-critico','Pensamiento Crítico en un Mundo de Desafíos','Objetivo General del Curso: Dotar a jóvenes con herramientas prácticas y conocimiento necesario para identificar influencias externas, desarrollar un pensamiento crítico sólido y…','Objetivo General del Curso: Dotar a jóvenes con herramientas prácticas y conocimiento necesario para identificar influencias externas, desarrollar un pensamiento crítico sólido y tomar decisiones conscientes, éticas y alineadas con sus valores y propósito personal, en un entorno lleno de desafíos como el narcotráfico, la desinformación mediática y la búsqueda de significado.','https://academiacabsa.com/wp-content/uploads/2025/07/close-up-sad-boy-portrait-2-600x400-1.jpg','Pensamiento crítico',9,'published','2013-01-11 16:53:39','2013-01-11 16:53:39','2026-07-29 19:46:19',0),(2561,'docentes-ia','Docentes en la Era de la IA: Innovando para el Futuro Educativo','Objetivo General del Curso: Empoderar a los docentes con herramientas, estrategias y conocimientos sobre el uso de la Inteligencia Artificial (IA) en la educación. El objetivo es…','Objetivo General del Curso: Empoderar a los docentes con herramientas, estrategias y conocimientos sobre el uso de la Inteligencia Artificial (IA) en la educación. El objetivo es explorar cómo la IA puede transformar las prácticas pedagógicas, mejorar la experiencia de aprendizaje y preparar a los estudiantes para un futuro impulsado por la tecnología.','https://academiacabsa.com/wp-content/uploads/2025/07/00054-3700994216-600x400-1.png','Tecnología',9,'published','2013-01-11 17:00:04','2013-01-11 17:00:04','2026-07-29 19:46:19',0),(2607,'ia-finanzas','Inteligencia Artificial para Gerentes Financieros','Objetivo General del Curso: Empoderar a los gerentes financieros con herramientas, estrategias y conocimientos sobre el uso de la Inteligencia Artificial (IA) en el ámbito…','Objetivo General del Curso: Empoderar a los gerentes financieros con herramientas, estrategias y conocimientos sobre el uso de la Inteligencia Artificial (IA) en el ámbito financiero. El objetivo es explorar cómo la IA puede transformar la gestión financiera, optimizar la toma de decisiones y mejorar la eficiencia operativa en las organizaciones.','https://academiacabsa.com/wp-content/uploads/2025/07/00024-669329969-600x400-1.png','Tecnología',15,'published','2013-01-16 19:16:24','2013-01-16 19:16:24','2026-07-29 19:46:19',0),(7707,'ia-basico','Curso Básico de IA','Objetivo General del Curso: Proporcionar a los participantes una visión sólida y práctica de la Inteligencia Artificial (IA), abarcando sus conceptos básicos, aplicaciones…','Objetivo General del Curso: Proporcionar a los participantes una visión sólida y práctica de la Inteligencia Artificial (IA), abarcando sus conceptos básicos, aplicaciones cotidianas, consideraciones éticas y estrategias para integrarla de manera efectiva en su vida personal y profesional.','https://academiacabsa.com/wp-content/uploads/2025/07/TaeJune15-scaled-600x400-1.jpg','Tecnología',32,'published','2015-01-30 19:18:49','2015-01-30 19:18:49','2026-08-04 17:53:37',0),(100007768,'bootcamp-docente-2','Bootcamp Docente','El Bootcamp Docente CABSA es una experiencia formativa diseñada para acompañar a las escuelas en la integración práctica de Academia CABSA, herramientas digitales e Inteligencia…','El Bootcamp Docente CABSA es una experiencia formativa diseñada para acompañar a las escuelas en la integración práctica de Academia CABSA, herramientas digitales e Inteligencia Artificial dentro del trabajo educativo. Su propósito es fortalecer la práctica docente mediante el uso estratégico de la plataforma, el desa','https://academiacabsa.com/wp-content/uploads/2026/05/BootCamp.png',NULL,0,'published','2026-05-11 23:50:08','2026-05-11 23:50:08','2026-07-29 19:46:19',0),(100007770,'el-uso-de-la-ia-en-la-educacion-especial','El uso de la IA en la educación especial ','Curso destinado al uso de la inteligencia Aritficial en la educación especial. ','','','Inovación ',1,'published','2026-08-03 21:05:03','2026-08-03 20:15:28','2026-08-03 21:05:03',0);
