INSERT INTO `academia_foros` VALUES (100000062,'salud-y-bienestar','Salud y Bienestar','Foro enfocado en el cuidado de mente y cuerpo, promoción de hábitos saludables y el equilibrio emocional.','❤️',2,'published','2025-07-11 06:38:02','2026-07-29 19:57:18'),(100000064,'educacion','Educación','Foro para compartir estrategias, experiencias y recursos entre docentes, estudiantes y familias.','?‍?',9,'published','2025-07-11 06:38:32','2026-07-29 19:57:18'),(100000066,'finanzas','Finanzas','Comunidad para aprender y compartir recursos sobre educación financiera y administración del dinero.','?',1,'published','2025-07-11 06:38:45','2026-07-29 19:57:18'),(100000068,'nueva-escuela-mexicana-nem','Nueva Escuela Mexicana (NEM)','Intercambio de prácticas y materiales sobre inclusión, equidad y formación integral en la NEM.','?',2,'published','2025-07-11 06:39:04','2026-07-29 19:57:18'),(100000070,'tecnologia','Tecnología','Espacio para explorar herramientas digitales aplicadas a la educación, el trabajo y la vida cotidiana.','?',1,'published','2025-07-11 06:39:20','2026-07-29 19:57:18'),(100000072,'escuela-para-padres','Escuela para Padres','Acompañamiento para familias sobre aprendizaje, convivencia, bienestar y educación en casa.','?',1,'published','2025-07-11 06:39:42','2026-07-29 19:57:18');
