  `status` enum('ACTIVE','COMPLETED','SUSPENDED','CANCELLED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `enrolled_at` datetime NOT NULL,
  `completed_at` datetime DEFAULT NULL,
