  UNIQUE KEY `soa_course_enrollments_user_id_course_id` (`user_id`,`course_id`),
  KEY `course_id` (`course_id`),
  KEY `scale_enrollment_updated_user_idx` (`updated_at`,`user_id`,`course_id`),
