  `lesson_type` enum('CONTENT','EXAM','PRACTICE','RESOURCE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CONTENT',
  `minimum_reading_seconds` int unsigned NOT NULL DEFAULT '300',
  PRIMARY KEY (`id`),
