DROP TABLE IF EXISTS `usuarios_codigos_beca_email`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuarios_codigos_beca_email` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `allowed_email` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL,
  `legacy_code_id` bigint unsigned DEFAULT NULL,
  `nivel_membresia_id` int unsigned DEFAULT NULL,
  `vigente_desde` date DEFAULT NULL,
  `vigente_hasta` date DEFAULT NULL,
  `max_usos` int unsigned NOT NULL DEFAULT '1',
  `usos_historicos` int unsigned NOT NULL DEFAULT '0',
  `usado_por_user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `usado_en` datetime DEFAULT NULL,
  `estado` enum('ACTIVE','REVOKED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'ACTIVE',
  `lote` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `notas` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `allowed_email` (`allowed_email`),
  KEY `beca_estado_idx` (`estado`),
  KEY `beca_lote_idx` (`lote`)
) ENGINE=InnoDB AUTO_INCREMENT=68601 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
