DROP TABLE IF EXISTS `usuarios_gestores_grupos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuarios_gestores_grupos` (
  `grupo_id` bigint unsigned NOT NULL,
  `docente_user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `limite_lugares` smallint unsigned NOT NULL DEFAULT '30',
  `creado_en` datetime NOT NULL,
  `actualizado_en` datetime NOT NULL,
  PRIMARY KEY (`grupo_id`,`docente_user_id`),
  UNIQUE KEY `teacher_managed_group_uq` (`docente_user_id`),
  KEY `docente_idx` (`docente_user_id`),
  CONSTRAINT `gestores_docente_fk` FOREIGN KEY (`docente_user_id`) REFERENCES `usuarios_cuentas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `gestores_grupo_fk` FOREIGN KEY (`grupo_id`) REFERENCES `usuarios_grupos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

