DROP TABLE IF EXISTS `usuarios_grupos_cuentas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuarios_grupos_cuentas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `grupo_id` bigint unsigned NOT NULL,
  `user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `creado_por_user_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `estado` enum('ACTIVE','SUSPENDED','REMOVED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `agregado_en` datetime NOT NULL,
  `actualizado_en` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `grupo_usuario_unique` (`grupo_id`,`user_id`),
  KEY `user_idx` (`user_id`),
  KEY `creador_idx` (`creado_por_user_id`),
  KEY `scale_group_state_user_idx` (`grupo_id`,`estado`,`user_id`),
  CONSTRAINT `grupos_cuentas_creador_fk` FOREIGN KEY (`creado_por_user_id`) REFERENCES `usuarios_cuentas` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `grupos_cuentas_grupo_fk` FOREIGN KEY (`grupo_id`) REFERENCES `usuarios_grupos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `grupos_cuentas_user_fk` FOREIGN KEY (`user_id`) REFERENCES `usuarios_cuentas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=426 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
