DROP TABLE IF EXISTS `usuarios_municipios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuarios_municipios` (
  `id_municipio` int NOT NULL AUTO_INCREMENT,
  `clave_municipio` char(3) DEFAULT NULL,
  `nombre_municipio` varchar(100) NOT NULL,
  `id_estado` int NOT NULL,
  PRIMARY KEY (`id_municipio`),
  UNIQUE KEY `uq_municipios_estado_nombre` (`id_estado`,`nombre_municipio`),
  UNIQUE KEY `uq_municipios_estado_clave` (`id_estado`,`clave_municipio`),
  KEY `fk_estados_idx` (`id_estado`),
  CONSTRAINT `fk_academia_estado_municipio` FOREIGN KEY (`id_estado`) REFERENCES `usuarios_estados` (`id_estado`)
