--
-- Table structure for table `usuarios_oficiales`
--

DROP TABLE IF EXISTS `usuarios_oficiales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuarios_oficiales` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `wp_user_id` bigint unsigned NOT NULL,
  `usuario` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `correo` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `nombre_visible` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `nombre` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `apellidos` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `rfc` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `estado_cuenta` enum('activo','inactivo') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'activo',
  `fecha_registro` datetime DEFAULT NULL,
  `es_fomaqro` tinyint(1) NOT NULL DEFAULT '0',
  `region_administrativa` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `coordinador` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `municipio_capturado` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `estado_oficial` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `clave_estado` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `municipio_oficial` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `clave_municipio` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `clave_geografica` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `codigo_postal` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `colonia` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `estatus_geografico` enum('completo','parcial','pendiente') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'pendiente',
  `estatus_identidad` enum('correcto','duplicado_probable','incompleto') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'incompleto',
  `observaciones_calidad` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci,
  `ultimo_login` datetime DEFAULT NULL,
  `total_inicios_sesion` bigint unsigned NOT NULL DEFAULT '0',
  `creado_en` datetime NOT NULL,
  `actualizado_en` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `wp_user_id_unique` (`wp_user_id`),
  KEY `correo_idx` (`correo`),
  KEY `rfc_idx` (`rfc`),
  KEY `estado_idx` (`clave_estado`,`estado_oficial`),
  KEY `municipio_idx` (`clave_estado`,`clave_municipio`),
  KEY `region_idx` (`region_administrativa`),
  KEY `cuenta_idx` (`estado_cuenta`),
  KEY `geografia_idx` (`estatus_geografico`),
  KEY `registro_idx` (`fecha_registro`),
  KEY `ultimo_login_idx` (`ultimo_login`)
) ENGINE=InnoDB AUTO_INCREMENT=520 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

